import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';
import { NotificationService } from '../../../core/services/notification.service';
import { passwordStrengthValidator, getPasswordStrength } from '../../../core/validators/password.validators';

@Component({
  selector: 'app-signup',
  templateUrl: './signup.component.html'
})
export class SignupComponent implements OnInit {

  signupForm!: FormGroup;
  errorMessage = '';
  isLoading = false;
  showPassword = false;

  // Tracks the strength label for the password bar
  passwordStrength: 'weak' | 'fair' | 'strong' | '' = '';

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private notifService: NotificationService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.signupForm = this.fb.group({
      name:     ['', [Validators.required]],
      email:    ['', [Validators.required, Validators.email]],
      username: ['', [Validators.required, Validators.minLength(3)]],
      // passwordStrengthValidator is our custom validator from password.validators.ts
      password: ['', [Validators.required, passwordStrengthValidator()]]
    });

    // Subscribe to password value changes to update the strength bar in real time
    this.signupForm.get('password')?.valueChanges.subscribe(value => {
      this.passwordStrength = getPasswordStrength(value);
    });
  }

  get f() { return this.signupForm.controls; }

  onSubmit(): void {
    this.errorMessage = '';
    this.signupForm.markAllAsTouched();
    if (this.signupForm.invalid) return;

    this.isLoading = true;

    this.authService.signup(this.signupForm.value).subscribe({
      next: () => {
        this.notifService.show('Account created! Please log in.', 'success');
        this.router.navigate(['/auth/login']);
      },
      error: (err) => {
        this.errorMessage = err.error?.message || err.error?.title || 'Registration failed.';
        this.isLoading = false;
      }
    });
  }

  togglePassword(): void {
    this.showPassword = !this.showPassword;
  }

  // Returns a human-friendly error for the password field
  getPasswordError(): string {
    const ctrl = this.f['password'];
    if (!ctrl.errors) return '';
    if (ctrl.errors['minLength'])  return 'Password must be at least 6 characters.';
    if (ctrl.errors['uppercase'])  return 'Must contain at least one uppercase letter.';
    if (ctrl.errors['number'])     return 'Must contain at least one number.';
    if (ctrl.errors['special'])    return 'Must contain at least one special character.';
    return 'Invalid password.';
  }
}
<div id="auth-screen">
  <div class="auth-wrapper">

    <div class="auth-left">
      <div class="auth-illustration">📐</div>
      <div class="auth-brand">Quantity Measurement</div>
      <div class="auth-tagline">Precision tools for length, weight,<br>volume &amp; temperature.</div>
    </div>

    <div class="auth-right">

      <div class="auth-tabs">
        <button class="auth-tab" routerLink="/auth/login">Login</button>
        <button class="auth-tab active">Signup</button>
      </div>

      <form class="auth-form active" [formGroup]="signupForm" (ngSubmit)="onSubmit()">

        <!-- Full Name -->
        <div class="form-group">
          <label class="form-label">Full Name</label>
          <input class="form-input" type="text" placeholder="Your name"
                 formControlName="name"
                 [class.is-invalid]="f['name'].invalid && f['name'].touched"/>
          <small class="field-error" *ngIf="f['name'].invalid && f['name'].touched">
            Full name is required.
          </small>
        </div>

        <!-- Email -->
        <div class="form-group">
          <label class="form-label">Email Id</label>
          <input class="form-input" type="email" placeholder="you@email.com"
                 formControlName="email"
                 [class.is-invalid]="f['email'].invalid && f['email'].touched"/>
          <small class="field-error" *ngIf="f['email'].errors?.['required'] && f['email'].touched">
            Email is required.
          </small>
          <small class="field-error" *ngIf="f['email'].errors?.['email'] && f['email'].touched">
            Please enter a valid email.
          </small>
        </div>

        <!-- Password with strength bar -->
        <div class="form-group">
          <label class="form-label">Password</label>
          <div class="form-input-wrap">
            <input class="form-input"
                   [type]="showPassword ? 'text' : 'password'"
                   placeholder="Min. 6 characters"
                   formControlName="password"
                   style="padding-right:40px"
                   [class.is-invalid]="f['password'].invalid && f['password'].touched"/>
            <button type="button" class="toggle-pw" (click)="togglePassword()">
              {{ showPassword ? '🙈' : '👁' }}
            </button>
          </div>
          <!-- Strength bar — class changes with passwordStrength value -->
          <div class="strength-row">
            <div class="strength-bar" [class]="'strength-bar ' + passwordStrength"></div>
            <span class="strength-label">
              {{ passwordStrength ? (passwordStrength | titlecase) : '' }}
            </span>
          </div>
          <small class="field-error" *ngIf="f['password'].invalid && f['password'].touched">
            {{ getPasswordError() }}
          </small>
        </div>

        <!-- Username -->
        <div class="form-group">
          <label class="form-label">Username</label>
          <input class="form-input" type="text" placeholder="Choose a username"
                 formControlName="username"
                 [class.is-invalid]="f['username'].invalid && f['username'].touched"/>
          <small class="field-error" *ngIf="f['username'].errors?.['required'] && f['username'].touched">
            Username is required.
          </small>
          <small class="field-error" *ngIf="f['username'].errors?.['minlength'] && f['username'].touched">
            Username must be at least 3 characters.
          </small>
        </div>

        <div class="auth-error" *ngIf="errorMessage" style="display:block">
          {{ errorMessage }}
        </div>

        <button type="submit" class="btn-primary" [disabled]="isLoading">
          {{ isLoading ? 'Creating account...' : 'Signup' }}
        </button>

        <div style="text-align:center;margin:15px 0;color:var(--muted);font-size:12px;font-weight:600">OR</div>

        <a href="https://localhost:5000/api/v1/auth/google"
           class="btn-primary"
           style="background:#fff;color:#333;border:1px solid #ddd;display:flex;align-items:center;justify-content:center;text-decoration:none;gap:10px;box-shadow:none">
          <svg width="18" height="18" viewBox="0 0 24 24">
            <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
            <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
            <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
            <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
          </svg>
          Continue with Google
        </a>

        <p style="text-align:center;margin-top:16px;font-size:13px;color:var(--muted)">
          Already have an account?
          <a routerLink="/auth/login" style="color:var(--primary);font-weight:600;text-decoration:none">Login</a>
        </p>

      </form>
    </div>
  </div>
</div>
